// Внешний канал іде по передній стороні руки (долоня ↔ плечо), спинной — плечо → крестец.
const SHP={L:D([0.215,1.49,0.022]),R:D([-0.215,1.49,0.022])},sSh={};
for(const s of ['L','R']){const p=PT['inner'+s],q=SHP[s],o=[0,0,0];let best=1e9;for(let d=0;d<p.L;d+=0.002){at(p,d,o);const e=Math.hypot(o[0]-q[0],o[1]-q[1],o[2]-q[2]);if(e<best){best=e;sSh[s]=d;}}}
// рука (мужской): шея → плечо → передний (внешний) канал до долоні → задній (внутренний) назад до плеча → спинной → крестец
const armTrack=s=>track(seg('inner'+s,0,sSh[s]),rev('outer'+s),seg('inner'+s,PT['inner'+s].L,sSh[s]),seg('spinal'+s));
// женский вариант = той самий шлях у зворотний бік
const revTrack=t=>track(...t.segs.slice().reverse().map(g=>({key:g.key,p:g.p,a:g.b,b:g.a,len:g.len})));
const revStages=(st,names)=>st.slice().reverse().map((s,i)=>stage(names[i],...s.tracks.map(revTrack)));
// ---- проходи крізь печі Хары (прямі: задній канал → центр печі → передній канал) ----
function line(...pts){const out=[];for(let i=0;i<pts.length-1;i++){const a=pts[i],b=pts[i+1],n=Math.max(2,Math.ceil(Math.hypot(b[0]-a[0],b[1]-a[1],b[2]-a[2])/0.005));
 for(let k=(i?1:0);k<=n;k++){const t=k/n;out.push(a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,a[2]+(b[2]-a[2])*t);}}return out;}
const atS=(key,s)=>{const o=[0,0,0];at(PT[key],s,o);return o;};
const sOnY=(key,y,from,to)=>{let best=from,bd=1e9;for(let s=from;s<=to;s+=0.002){const o=atS(key,s),d=Math.abs(o[1]-y);if(d<bd){bd=d;best=s;}}return best;};
const BL=PT.back.L,FL=PT.front.L;
const sNear=(key,q,from,to)=>{let best=from,bd=1e9;for(let s=from;s<=to;s+=0.001){const o=atS(key,s),d=Math.hypot(o[0]-q[0],o[1]-q[1],o[2]-q[2]);if(d<bd){bd=d;best=s;}}return best;};
const sF1=sOnY('front',1.051,0,0.3),sF2=sOnY('front',1.419,0.3,0.7); /* 19:00: печі як на картинці — нижня й середня на 3 см вище */          // переднесрединный: нижня / середня піч
const sB2=sOnY('back',1.419,0.5,BL),sB3=sNear('back',D([0,1.745,-0.0252]),0.2,0.45),sH3=sNear('back',D([0,1.7736,0.1282]),0,0.2); // верхня піч нахилена на 10,6° — її передній край вище центру // заднесрединный: хребет біля середньої, потилиця і лоб біля верхньої
PT.h1=mkPath(line(atS('back',BL),D([0,1.051,0.062]),atS('front',sF1)));
PT.h2=mkPath(line(atS('back',sB2),D([0,1.419,0.064]),atS('front',sF2)));
PT.h3=mkPath(line(atS('back',sB3),D([0,1.7593,0.0515]),atS('back',sH3)));
// промежина (низ таза) → крестец: короткий з'єднувальний відрізок (каналу в моделі немає — світиться лише трубка шляху)
{const p0=atS('front',0),p2=atS('back',BL),c=[0,Math.min(p0[1],p2[1])+0.004,p2[2]+0.004],pts=[];
 for(let i=0;i<=24;i++){const t=i/24,q=1-t;pts.push(q*q*p0[0]+2*q*t*c[0]+t*t*p2[0],q*q*p0[1]+2*q*t*c[1]+t*t*p2[1],q*q*p0[2]+2*q*t*c[2]+t*t*p2[2]);}PT.pc=mkPath(pts);}
