function ptVis(C,g){if(!C._pv)C._pv=new Map();if(C._pv.has(g))return C._pv.get(g);let v=false;if(g.req&&!C.used.has(g.req)){C._pv.set(g,false);return false;} /* груди — лише коло з руками */const o=[0,0,0];
 C.stages.forEach(st=>st.tracks.forEach(t=>t.segs.forEach(sg=>{if(v)return;const n=Math.max(2,Math.ceil(sg.len/0.01));for(let i=0;i<=n&&!v;i++){at(sg.p,sg.a+(sg.b-sg.a)*i/n,o);if(Math.hypot(o[0]-g.p[0],o[1]-g.p[1],o[2]-g.p[2])<0.04)v=true;}})));
 C._pv.set(g,v);return v;}
function trackPos(t,d,o){let g=t.segs[t.segs.length-1];for(const s of t.segs){if(d<s.d0+s.len){g=s;break;}}
 const x=Math.min(g.len,Math.max(0,d-g.d0));trackPos.s=g.a+(g.b>g.a?x:-x);at(g.p,trackPos.s,o);trackPos.seg=g;return g.key;}

let objs={},u=0,cur=null,lastStage=-9;const level={};for(const k in CH)level[k]=0;
const BALLS=[];let nb=0;
function vis(k){const o=objs[k];return !o||o.visible;}
function push(p,r,a,key){if(a<=0.003||r<=0)return;if(key&&!vis(key))return;if(nb>=MAXB)return;const b=BALLS[nb]||(BALLS[nb]=[0,0,0,0,0]);b[0]=p[0];b[1]=p[1];b[2]=p[2];b[3]=r;b[4]=a;nb++;}
const tmp=[0,0,0];
